// CriarPedido is the resolver for the criarPedido field.
func (r *mutationResolver) CriarPedido(ctx context.Context, request model.CriarPedidoRequest) (bool, error) {
	if r.PublicarPedidoCriado == nil {
		return false, errors.New("publicador do evento pedido.criado não configurado")
	}

	id, err := service.CriarPedidoComItens(request.Itens)
	if err != nil {
		switch {
		case errors.Is(err, service.ErrPedidoSemItens),
			errors.Is(err, service.ErrItemInvalido),
			errors.Is(err, service.ErrProdutoInexistente),
			errors.Is(err, service.ErrItemDuplicado):
			return false, err
		default:
			return false, errors.New("não foi possível criar o pedido")
		}
	}

	// Só publica depois do commit do pedido
	itensDTO := make([]dto.ItemDTO, 0, len(request.Itens))
	for _, item := range request.Itens {
		itensDTO = append(itensDTO, dto.ItemDTO{
			ProdutoId:  int(item.ProdutoID),
			Quantidade: int(item.Quantidade),
		})
	}

	pedido := dto.PedidoCriadoDTO{Id: id, Itens: itensDTO}

	if err := r.PublicarPedidoCriado(pedido); err != nil {
		log.Printf("[ERRO-MS-PRINCIPAL] Pedido criado, mas falhou ao publicar pedido.criado: %v", err)
	}

	return true, nil
}

// RemoverPedido is the resolver for the removerPedido field.
func (r *mutationResolver) RemoverPedido(ctx context.Context, request model.RemoverPedidoRequest) (bool, error) {
	if r.PublicarPedidoExcluido == nil {
		return false, errors.New("publicador do evento pedido.excluido não configurado")
	}

	if err := service.ExcluirPedido(int(request.ID)); err != nil {
		if errors.Is(err, service.ErrPedidoNaoEncontrado) {
			return false, errors.New("pedido não encontrado")
		}
		return false, errors.New("não foi possível excluir o pedido")
	}

	// Avisa o MS Estoque, que devolve as reservas no banco dele
	pedido := dto.PedidoDTO{Id: int(request.ID)}

	if err := r.PublicarPedidoExcluido(pedido); err != nil {
		log.Printf("[ERRO-MS-PRINCIPAL] Pedido excluído, mas falhou ao publicar pedido.excluido: %v", err)
	}

	return true, nil
}

// Produtos is the resolver for the produtos field.
